def make_styles():
    styles = getSampleStyleSheet()
    styles.add(ParagraphStyle(name="CoverTitleG", parent=styles["Title"], fontName="Helvetica-Bold", fontSize=26, leading=31, textColor=NAVY, alignment=TA_LEFT, spaceAfter=16))
    styles.add(ParagraphStyle(name="CoverSubtitleG", parent=styles["Normal"], fontName="Helvetica", fontSize=13, leading=18, textColor=MUTED, spaceAfter=10))
    styles.add(ParagraphStyle(name="PageTitleG", parent=styles["Heading1"], fontName="Helvetica-Bold", fontSize=15, leading=18, textColor=NAVY, spaceBefore=0, spaceAfter=10, keepWithNext=True))
    styles.add(ParagraphStyle(name="BodyG", parent=styles["BodyText"], fontName="Helvetica", fontSize=8.6, leading=11.2, textColor=INK, spaceAfter=5))
    styles.add(ParagraphStyle(name="SmallG", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.8, leading=10, textColor=INK, spaceAfter=3))
    styles.add(ParagraphStyle(name="LabelG", parent=styles["BodyText"], fontName="Helvetica-Bold", fontSize=8.2, leading=10, textColor=NAVY, spaceBefore=4, spaceAfter=2, keepWithNext=True))
    styles.add(ParagraphStyle(name="NoteG", parent=styles["BodyText"], fontName="Helvetica-Oblique", fontSize=8, leading=10.5, textColor=MUTED, spaceAfter=5))
    styles.add(ParagraphStyle(name="TableG", parent=styles["BodyText"], fontName="Helvetica", fontSize=7.6, leading=9.4, textColor=INK))
    return styles


STYLES = make_styles()


def para(text: str, style: str = "BodyG") -> Paragraph:
    return Paragraph(escape(text), STYLES[style])


def labeled(label: str, text: str) -> Paragraph:
    return Paragraph(f"<b>{escape(label)}:</b> {escape(text)}", STYLES["BodyG"])


def bullet(text: str) -> Paragraph:
    return Paragraph(f"<font color=\"#C7AD72\"><b>-</b></font> {escape(text)}", STYLES["BodyG"])


def draw_page(canvas, doc, short_title: str):
    canvas.saveState()
    width, height = letter
    canvas.setStrokeColor(GOLD)
    canvas.setLineWidth(1.2)
    canvas.line(0.65 * inch, height - 0.44 * inch, width - 0.65 * inch, height - 0.44 * inch)
    canvas.setFont("Helvetica-Bold", 7.5)
    canvas.setFillColor(NAVY)
    canvas.drawString(0.65 * inch, height - 0.34 * inch, "GOMBEY AI | SYNTHETIC TEST CORPUS")
    canvas.setFont("Helvetica", 7.2)
    canvas.setFillColor(MUTED)
    canvas.drawRightString(width - 0.65 * inch, height - 0.34 * inch, short_title[:62])
    canvas.setStrokeColor(colors.HexColor("#D8DEE5"))
    canvas.line(0.65 * inch, 0.48 * inch, width - 0.65 * inch, 0.48 * inch)
    canvas.setFont("Helvetica", 7.2)
    canvas.setFillColor(MUTED)
    canvas.drawString(0.65 * inch, 0.31 * inch, "Fictional training data. Do not use as real client policy or advice.")
    canvas.drawRightString(width - 0.65 * inch, 0.31 * inch, f"Page {doc.page}")
    canvas.restoreState()


def build_pdf(path: Path, title: str, subtitle: str, short_title: str, pages: list[list]):
    doc = BaseDocTemplate(str(path), pagesize=letter, leftMargin=0.68 * inch, rightMargin=0.68 * inch, topMargin=0.65 * inch, bottomMargin=0.62 * inch, title=title, author="Gombey AI Synthetic QA", subject="Fictional creative-agency retrieval evaluation")
    frame = Frame(doc.leftMargin, doc.bottomMargin, doc.width, doc.height, id="normal", leftPadding=0, rightPadding=0, topPadding=0, bottomPadding=0)
    doc.addPageTemplates([PageTemplate(id="main", frames=frame, onPage=lambda c, d: draw_page(c, d, short_title))])
    story = [Spacer(1, 1.3 * inch), para(title, "CoverTitleG"), para(subtitle, "CoverSubtitleG"), Spacer(1, 0.2 * inch)]
    story += [para("Purpose and safe use", "LabelG"), para("This manual is a deliberately fictional, long-form retrieval and workflow test set for a Gombey AI staging workspace. All businesses, people, budgets, dates, offers, and performance targets are invented. Use synthetic questions only. The documents are designed to test exact fact retrieval, cross-document synthesis, citations, uncertainty handling, approval boundaries, and safe drafting; they are not real customer guidance.")]
    story += [para("How to evaluate", "LabelG"), para("Upload the three manuals to one admin-managed shared File Search agent. Ask members to select that agent, request a cited fact, compare it with the separate answer key, ask at least one unsupported question, and ask for a draft action plan. A pass requires correct facts, a relevant source citation, no invented answer, and a clear statement when the platform cannot perform an external action.")]
    story += [para("Corpus map", "LabelG"), para("Manual 1 defines fictional studio operations and approval rules. Manual 2 contains 30 separate campaign briefs with unique dates, budgets, owners, offers, channels, metrics, and claims boundaries. Manual 3 contains 30 operational procedures with role, trigger, inputs, steps, evidence, and stop conditions.")]
    story += [Spacer(1, 0.25 * inch), para("Synthetic workspace: Juniper & Slate Creative Studio", "LabelG"), para("Fictional office hours are Monday through Friday, 9:00 a.m. to 5:00 p.m. Eastern. Owner: Morgan Ellis. Operations lead: Riley Chen. Creative director: Dana Patel. Account leads: Priya Nair and Elliot Brooks. Performance analyst: Marcus Reed. Every customer-facing release requires the named client approver.")]
    story.append(PageBreak())
    for page_index, page_story in enumerate(pages, start=1):
        story.extend(page_story)
        if page_index != len(pages):
            story.append(PageBreak())
    doc.build(story)


def operations_pages():
    pages = []
    for idx, (title, owner, trigger, standard, steps, evidence, escalate) in enumerate(OPS, start=1):
        page = [para(f"{idx:02d}. {title}", "PageTitleG"), para(standard), labeled("Process owner", owner), labeled("Use this procedure when", trigger), para("Required sequence", "LabelG")]
        page.extend(bullet(step) for step in steps)
        page += [labeled("Record and verify", evidence), labeled("Stop or escalate", escalate), para(f"Application note: For {title.lower()}, the operator should explain what is known, identify what remains unknown, and leave a human owner accountable for the next consequential decision. A polished document or plausible model response is not approval. When the procedure involves a source file, retain a dated version and test at least one expected fact plus one absent fact before declaring the task complete.", "NoteG")]
        pages.append(page)
    return pages


def campaign_rows():
    result = []
    first_launch = date(2026, 11, 4)
    for i, (company, sector, campaign, objective, offer, channel, caveat) in enumerate(CLIENTS):
        launch = first_launch + timedelta(days=2 * i)
        review = launch - timedelta(days=8)
        budget = 2400 + 175 * i
        metric = METRICS[i % len(METRICS)]
        target_value = 410 + 37 * i if i % len(METRICS) != 2 else f"{2.4 + 0.1 * i:.1f}%"
        target = f"{target_value} {metric}" if isinstance(target_value, int) else f"{target_value} {metric}"
        approver = APPROVERS[i % len(APPROVERS)]
        lead = TEAM[i % len(TEAM)]
        cta = CTAS[i % len(CTAS)]
        deliverables = DELIVERABLE_SETS[i % len(DELIVERABLE_SETS)]
        code = f"JS-C{i + 1:02d}"
        result.append({"code": code, "company": company, "sector": sector, "campaign": campaign, "objective": objective, "offer": offer, "channel": channel, "caveat": caveat, "launch": launch.isoformat(), "review": review.isoformat(), "budget": f"${budget:,}", "approver": approver, "lead": lead, "cta": cta, "deliverables": deliverables, "metric": metric, "target": target, "assets": 4 + (i % 5), "timezone": "America/New_York"})
    return result


def campaign_pages(rows):
    pages = []
    for i, row in enumerate(rows, start=1):
        page = [para(f"{i:02d}. {row['code']} | {row['company']}", "PageTitleG"), para(f"Campaign: {row['campaign']}. This fictional client brief is the sole source of approved project facts for this code. The goal is {row['objective']}. Treat the target as a planning objective, not a guarantee of business results.")]
        facts = [
            [para("Field", "TableG"), para("Approved project value", "TableG")],
            [para("Client and sector", "TableG"), para(f"{row['company']} | {row['sector']}", "TableG")],
            [para("Campaign code", "TableG"), para(row["code"], "TableG")],
            [para("Launch / first review", "TableG"), para(f"{row['launch']} / {row['review']}", "TableG")],
            [para("Production budget cap", "TableG"), para(row["budget"], "TableG")],
            [para("Account lead / client approver", "TableG"), para(f"{row['lead']} / {row['approver']}", "TableG")],
            [para("Channel / call to action", "TableG"), para(f"{row['channel']} / {row['cta']}", "TableG")],
            [para("Offer / KPI target", "TableG"), para(f"{row['offer']} / {row['target']}", "TableG")],
            [para("Deliverables", "TableG"), para(row["deliverables"], "TableG")],
        ]
        table = Table(facts, colWidths=[1.55 * inch, 5.45 * inch], repeatRows=1, hAlign="LEFT")
        table.setStyle(TableStyle([("BACKGROUND", (0, 0), (-1, 0), NAVY), ("TEXTCOLOR", (0, 0), (-1, 0), colors.white), ("BACKGROUND", (0, 1), (0, -1), PALE), ("GRID", (0, 0), (-1, -1), 0.35, colors.HexColor("#D5DCE4")), ("VALIGN", (0, 0), (-1, -1), "TOP"), ("LEFTPADDING", (0, 0), (-1, -1), 5), ("RIGHTPADDING", (0, 0), (-1, -1), 5), ("TOPPADDING", (0, 0), (-1, -1), 4), ("BOTTOMPADDING", (0, 0), (-1, -1), 4)]))
        page += [table, Spacer(1, 6), para("Audience and message", "LabelG"), para(f"The account lead must confirm the intended audience with {row['approver']} before writing final copy. The campaign may use only the stated offer: {row['offer']}. Do not add a discount, eligibility condition, inventory promise, or deadline that is not present in this brief. Use the CTA '{row['cta']}' exactly or present a changed CTA for approval.")]
        page += [para("Claims boundary", "LabelG"), para(f"The explicit limitation is: {row['caveat']} Supporting evidence must be checked before using a factual claim. If a customer asks for a stronger statement, record it as a question for the approver; do not convert a suggestion into an approved fact.")]
        page += [para("Review and measurement", "LabelG"), para(f"The first client review is due {row['review']}; final client approval belongs to {row['approver']}. The account lead is {row['lead']}. Track {row['metric']} using the campaign's approved source, date range, and attribution definition. The target is {row['target']}; it is not a promise. The production budget cap is {row['budget']}, separate from any agency fee unless a signed contract says otherwise.")]
        page += [para("Release checklist", "LabelG"), bullet(f"Prepare {row['assets']} planned creative assets and the agreed deliverable set; identify each version."), bullet(f"Verify {row['launch']} as the launch date, {row['channel']} as the approved channel, and the destination behind '{row['cta']}'."), bullet("Send the exact proof to the named approver; record explicit approval before any customer-facing release."), bullet("If an input is absent, label it unknown and ask the owner rather than inferring it.")]
        page.append(para(f"Planning note: This page does not grant access to {row['company']}'s production systems, authorize a real advertisement, or confirm that the offer is currently available. It is a fictional test brief only.", "NoteG"))
        pages.append(page)
    return pages


